std::vector<Polygon2d> result;

for (auto fit = arr.faces_begin(); fit != arr.faces_end(); ++fit) {
    // Check if face is bounded (finite)
    if (fit->is_finite()) {
        Polygon2d polygon;

        // Get the outer boundary (outer CCB - counter-clockwise boundary)
        auto ccb_start = fit->outer_ccb();
        auto it = ccb_start;
        do {
            polygon.push_back(Point2d(it->point().x(), it->point().y()));
            ++it;
        } while (it != ccb_start);

        result.push_back(polygon);
    }
}

return result;

